
import pretty_midi

# Load the MIDI file generated by Transkun
midi = pretty_midi.PrettyMIDI("examples/output2.mid")

# Gather all notes and sustain pedal events
notes = []
sustain_events = []

for instrument in midi.instruments:
    notes.extend(instrument.notes)

    for event in instrument.control_changes:
        if event.number == 64:
            sustain_events.append(event)

# Sort notes by their starting times
notes.sort(key=lambda note: note.start)
sustain_events.sort(key=lambda event: event.time)

print("=== TRANSKUN MIDI ANALYSIS ===")
print("Total notes:", len(notes))
print("Sustain pedal events:", len(sustain_events))

print("\n=== FIRST 10 NOTES ===")

for note in notes[:10]:
    name = pretty_midi.note_number_to_name(note.pitch)
    duration = note.end - note.start

    print(
        f"{name:4} | "
        f"Start: {note.start:.3f}s | "
        f"End: {note.end:.3f}s | "
        f"Duration: {duration:.3f}s | "
        f"Velocity: {note.velocity}"
    )

print("\n=== STATISTICS ===")

if notes:
    avg_velocity = sum(n.velocity for n in notes) / len(notes)
    longest_note = max(n.end - n.start for n in notes)
    middle_c_count = sum(n.pitch == 60 for n in notes)

    print(f"Average velocity: {avg_velocity:.2f}")
    print(f"Longest note: {longest_note:.3f}s")
    print(f"Middle C notes: {middle_c_count}")
else:
    print("No note events were detected.")

print("\n=== FIRST 10 SUSTAIN EVENTS ===")

for event in sustain_events[:10]:
    print(f"Time: {event.time:.3f}s | Value: {event.value}")
